"use client";

import {
  clampMagneticOffset,
  clampMagneticStrength,
  MOTION_DEFAULTS,
} from "./clamp";
import { FINE_POINTER_QUERY, shouldEnableMagnetic } from "./motion-policy";
import { motion, useMotionValue, useReducedMotion, useSpring } from "motion/react";
import {
  useEffect,
  useRef,
  useState,
  type ElementType,
  type PointerEvent,
  type ReactNode,
} from "react";

function cn(...inputs: Array<string | undefined | false | null>) {
  return inputs.filter(Boolean).join(" ");
}

export type MagneticProps = {
  children: ReactNode;
  className?: string;
  as?: ElementType;
  strength?: number;
  maxOffset?: number;
};

export function Magnetic({
  children,
  className,
  as = "div",
  strength = MOTION_DEFAULTS.magneticStrength,
  maxOffset = MOTION_DEFAULTS.magneticMaxOffset,
}: MagneticProps) {
  const reduce = useReducedMotion();
  const Tag = as as ElementType;
  const Component = motion.create(Tag);
  const ref = useRef<HTMLElement | null>(null);
  const [finePointer, setFinePointer] = useState(false);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const springX = useSpring(x, { stiffness: 240, damping: 20, mass: 0.35 });
  const springY = useSpring(y, { stiffness: 240, damping: 20, mass: 0.35 });
  const clampedStrength = clampMagneticStrength(strength);
  const clampedOffset = clampMagneticOffset(maxOffset);

  useEffect(() => {
    const media = window.matchMedia(FINE_POINTER_QUERY);
    const update = () => {
      setFinePointer(media.matches);
    };
    update();
    media.addEventListener("change", update);
    return () => {
      media.removeEventListener("change", update);
    };
  }, []);

  function reset() {
    x.set(0);
    y.set(0);
  }

  function onPointerMove(event: PointerEvent<HTMLElement>) {
    if (
      !shouldEnableMagnetic({
        reduce,
        finePointer,
        pointerType: event.pointerType,
      })
    ) {
      reset();
      return;
    }
    const node = ref.current;
    if (!node) {
      return;
    }
    const rect = node.getBoundingClientRect();
    const dx = event.clientX - (rect.left + rect.width / 2);
    const dy = event.clientY - (rect.top + rect.height / 2);
    x.set(Math.max(-clampedOffset, Math.min(clampedOffset, dx * clampedStrength)));
    y.set(Math.max(-clampedOffset, Math.min(clampedOffset, dy * clampedStrength)));
  }

  return (
    <Component
      ref={ref}
      className={cn(className)}
      style={{ x: springX, y: springY }}
      onPointerMove={onPointerMove}
      onPointerLeave={reset}
      onPointerCancel={reset}
    >
      {children}
    </Component>
  );
}

export const MOTION_DEFAULTS = {
  staggerInterval: 0.08,
  staggerDelay: 0,
  staggerAmount: 0.3,
  staggerOnce: true,
  staggerY: 16,
  parallaxSpeed: 0.2,
  parallaxSpeedMin: 0,
  parallaxSpeedMax: 0.45,
  parallaxRangePx: 72,
  magneticStrength: 0.35,
  magneticStrengthMin: 0,
  magneticStrengthMax: 1,
  magneticMaxOffset: 16,
  magneticMaxOffsetMin: 0,
  magneticMaxOffsetMax: 32,
  imageScale: 1,
  imageScaleMin: 1,
  imageScaleMax: 1.08,
  imageRevealY: 24,
  ease: [0.16, 1, 0.3, 1] as const,
  duration: 0.55,
};

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function clampParallaxSpeed(speed: number): number {
  return clamp(
    speed,
    MOTION_DEFAULTS.parallaxSpeedMin,
    MOTION_DEFAULTS.parallaxSpeedMax,
  );
}

export function clampMagneticStrength(strength: number): number {
  return clamp(
    strength,
    MOTION_DEFAULTS.magneticStrengthMin,
    MOTION_DEFAULTS.magneticStrengthMax,
  );
}

export function clampMagneticOffset(offset: number): number {
  return clamp(
    offset,
    MOTION_DEFAULTS.magneticMaxOffsetMin,
    MOTION_DEFAULTS.magneticMaxOffsetMax,
  );
}

export function clampImageScale(scale: number): number {
  return clamp(
    scale,
    MOTION_DEFAULTS.imageScaleMin,
    MOTION_DEFAULTS.imageScaleMax,
  );
}

export function clampStaggerInterval(interval: number): number {
  return clamp(interval, 0, 1);
}

export function parallaxTravelPx(speed: number): number {
  return clampParallaxSpeed(speed) * MOTION_DEFAULTS.parallaxRangePx;
}

export const FINE_POINTER_QUERY = "(pointer: fine) and (hover: hover)";

export function shouldAnimateMotion(
  reduce: boolean | null | undefined,
): boolean {
  return !reduce;
}

export function shouldEnableParallax(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (
    options.disableBelow != null &&
    options.viewportWidth != null &&
    options.viewportWidth < options.disableBelow
  ) {
    return false;
  }
  return true;
}

export function shouldEnableMagnetic(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (!options.finePointer) {
    return false;
  }
  if (
    options.pointerType &&
    options.pointerType !== "mouse" &&
    options.pointerType !== "pen"
  ) {
    return false;
  }
  return true;
}

export function shouldEnablePointerAccent(options: {
  enabled: boolean;
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!options.enabled) {
    return false;
  }
  return shouldEnableMagnetic({
    reduce: options.reduce,
    finePointer: options.finePointer,
    pointerType: options.pointerType,
  });
}
